CREATE OR REPLACE FUNCTION public._user_issue_for_admin(p_id uuid)
 RETURNS public.user_issues
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v public.user_issues%rowtype;
begin
  if not public._user_issue_admin() then
    raise exception 'Only an administrator can manage reported problems' using errcode = '42501';
  end if;
  select * into v from public.user_issues where id = p_id for update;
  if not found then
    raise exception 'Problem report not found' using errcode = 'P0002';
  end if;
  if not public.is_super_admin() and v.organisation_id is distinct from public.app_current_org() then
    raise exception 'Problem report not found' using errcode = 'P0002';
  end if;
  return v;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.accident_apply_tokens(tpl text, acc public.accidents, v_dept text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_company text;
  v_base    text;
  o         text := tpl;
BEGIN
  v_company := btrim(COALESCE((SELECT value FROM public.system_config WHERE key='company_name'), 'Tyre Pulse'), '"');
  v_base    := btrim(COALESCE((SELECT value FROM public.system_config WHERE key='app_url'), 'https://tyrepulse.app'), '"');
  o := replace(o, '{{reference_no}}', COALESCE(acc.reference_no,'-'));
  o := replace(o, '{{company}}',      COALESCE(NULLIF(v_company,''),'Tyre Pulse'));
  o := replace(o, '{{site}}',         COALESCE(acc.site,'-'));
  o := replace(o, '{{asset_no}}',     COALESCE(acc.asset_no,'-'));
  o := replace(o, '{{plate_number}}', COALESCE(NULLIF(acc.plate_number,''),'-'));
  o := replace(o, '{{driver_name}}',  COALESCE(NULLIF(acc.driver_name,''),'-'));
  o := replace(o, '{{incident_date}}',COALESCE(to_char(acc.incident_date,'DD Mon YYYY'),'-')
                                      || CASE WHEN COALESCE(acc.incident_time,'')<>'' THEN ' '||acc.incident_time ELSE '' END);
  o := replace(o, '{{location}}',     COALESCE(NULLIF(acc.location,''),'-'));
  o := replace(o, '{{severity}}',     public.accident_severity_label(acc.severity));
  o := replace(o, '{{stage_label}}',  public.accident_stage_label(acc.workflow_stage));
  o := replace(o, '{{vor_label}}',    CASE WHEN acc.vor THEN 'Yes'
                                        || CASE WHEN acc.vor_since IS NOT NULL THEN ' (since '||to_char(acc.vor_since,'DD Mon YYYY')||')' ELSE '' END
                                        ELSE 'No' END);
  o := replace(o, '{{estimated_cost}}', COALESCE(acc.estimated_damage_cost::text,'-'));
  o := replace(o, '{{approved_cost}}',  COALESCE(acc.approved_repair_amount::text, acc.final_amount::text,'-'));
  o := replace(o, '{{claim_status}}',   COALESCE(acc.claim_status,'none'));
  o := replace(o, '{{department}}',     COALESCE(NULLIF(v_dept,''),'-'));
  o := replace(o, '{{pending_action}}', public.accident_pending_action(acc.workflow_stage));
  o := replace(o, '{{due_date}}',       COALESCE(to_char(acc.target_date,'DD Mon YYYY'), to_char(acc.sla_due_at,'DD Mon YYYY'),'-'));
  o := replace(o, '{{link}}',           v_base || '/accidents/' || acc.id::text);
  RETURN o;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.admin_list_access_audit(p_limit integer DEFAULT 100, p_target uuid DEFAULT NULL::uuid)
 RETURNS SETOF public.access_audit
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Only a Super Admin can read the access audit.' USING errcode = '42501'; END IF;
  RETURN QUERY SELECT * FROM public.access_audit WHERE (p_target IS NULL OR target_user = p_target) ORDER BY at DESC LIMIT GREATEST(COALESCE(p_limit, 100), 1);
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.checklist_template_snapshot(p_template public.checklist_templates)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_strip_nulls(jsonb_build_object(
    'template_id', p_template.id,
    'version', p_template.version,
    'name', p_template.name,
    'description', p_template.description,
    'category', p_template.category,
    'country', p_template.country,
    'status', p_template.status,
    'require_signature', p_template.require_signature,
    'require_approval', p_template.require_approval,
    'require_area_manager', p_template.require_area_manager,
    'scored', p_template.scored,
    'pass_threshold', p_template.pass_threshold,
    'assignee_roles', p_template.assignee_roles,
    'doc_prefix', p_template.doc_prefix,
    'min_interval_days', p_template.min_interval_days,
    'name_i18n', p_template.name_i18n,
    'description_i18n', p_template.description_i18n,
    'option_sets', p_template.option_sets,
    'fields', p_template.fields
  ));
$function$;
