CREATE OR REPLACE FUNCTION public.consume_event_accident_case_notify(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org        uuid := ev.organisation_id;
  v_country    text := NULLIF(ev.payload ->> 'country', '');
  v_accident   uuid := NULLIF(ev.payload ->> 'accident_id', '')::uuid;
  v_owner      uuid := NULLIF(ev.payload ->> 'owner_id', '')::uuid;
  v_requester  uuid := NULLIF(ev.payload ->> 'requested_by', '')::uuid;
  v_reviewer   uuid := NULLIF(ev.payload ->> 'reviewer_id', '')::uuid;
  v_ws         text := NULLIF(ev.payload ->> 'workstream_key', '');
  v_appr       text := NULLIF(ev.payload ->> 'approval_type', '');
  v_level      text := NULLIF(ev.payload ->> 'level', '');
  v_decision   text := NULLIF(ev.payload ->> 'decision', '');
  v_ntype      text := 'info';
  v_ref        text;
  v_asset      text;
  v_site       text;
  v_ctx        text;
  v_title      text;
  v_body       text;
  v_targets    uuid[] := '{}';
  v_recipients jsonb;
  v_wf_payload jsonb;
  v_gate       text;
  v_emails_on  boolean;
  v_to_raw     text;
  v_cc_raw     text;
  v_prefix     text;
  v_emails     text[];
  v_actor_name text;
  v_actor_role text;
  v_signature  text := 'System';
  v_subject    text;
  v_html       text;
BEGIN
  IF v_accident IS NOT NULL THEN
    SELECT COALESCE(NULLIF(a.reference_no, ''), NULLIF(a.case_no, ''), 'Case'),
           COALESCE(NULLIF(a.asset_no, ''), 'Unknown asset'),
           COALESCE(NULLIF(a.site, ''), v_country, '')
      INTO v_ref, v_asset, v_site
      FROM public.accidents a
     WHERE a.id = v_accident;
  END IF;
  v_ref  := COALESCE(v_ref, 'Case');
  v_asset := COALESCE(v_asset, 'Unknown asset');
  v_ctx  := v_ref || ' | ' || v_asset || CASE WHEN NULLIF(v_site,'') IS NOT NULL
                                              THEN ' (' || v_site || ')' ELSE '' END;

  IF ev.event_type = 'accident.workstream_assigned' THEN
    v_ntype := 'info';
    v_title := 'Workstream assigned - ' || v_asset;
    v_body  := COALESCE(v_ws, 'A workstream') || ' assigned. ' || v_ctx;
    IF v_owner IS NOT NULL THEN
      v_targets := ARRAY[v_owner];
    END IF;

  ELSIF ev.event_type = 'accident.approval_requested' THEN
    v_ntype := 'warning';
    v_title := 'Approval requested - ' || v_asset;
    v_body  := COALESCE(v_appr, 'An approval')
               || CASE WHEN NULLIF(ev.payload ->> 'amount','') IS NOT NULL
                       THEN ' (' || (ev.payload ->> 'amount') || ')' ELSE '' END
               || ' requires a decision. ' || v_ctx;

  ELSIF ev.event_type = 'accident.closure_requested' THEN
    v_ntype := 'info';
    v_title := 'Closure requested - ' || v_asset;
    v_body  := 'Closure review'
               || CASE WHEN v_level IS NOT NULL THEN ' (' || v_level || ')' ELSE '' END
               || ' awaiting a decision. ' || v_ctx;

  ELSIF ev.event_type = 'accident.closure_decided' THEN
    v_ntype := CASE WHEN v_decision = 'approved' THEN 'success'
                    WHEN v_decision = 'rejected' THEN 'warning' ELSE 'info' END;
    v_title := 'Closure ' || COALESCE(v_decision, 'updated') || ' - ' || v_asset;
    v_body  := 'Closure review'
               || CASE WHEN v_level IS NOT NULL THEN ' (' || v_level || ')' ELSE '' END
               || ' decided: ' || COALESCE(v_decision, 'updated') || '. ' || v_ctx;
    IF v_requester IS NOT NULL THEN v_targets := array_append(v_targets, v_requester); END IF;

  ELSE
    RETURN;
  END IF;

  IF ev.event_type IN ('accident.approval_requested','accident.closure_requested','accident.closure_decided')
     OR (ev.event_type = 'accident.workstream_assigned' AND v_owner IS NULL) THEN
    v_targets := v_targets || COALESCE((
      SELECT array_agg(p.id)
        FROM public.profiles p
       WHERE p.role IN ('Admin','Manager','Director')
         AND COALESCE(p.locked, false) = false
         AND (p.approved IS NULL OR p.approved = true)
         AND (v_org IS NULL OR p.organisation_id = v_org OR p.org_id = v_org)
         AND (v_country IS NULL
              OR p.country IS NULL OR cardinality(p.country) = 0
              OR v_country = ANY (p.country))
    ), '{}'::uuid[]);
  END IF;

  SELECT COALESCE(array_agg(DISTINCT t), '{}'::uuid[]) INTO v_targets
    FROM unnest(v_targets) AS t WHERE t IS NOT NULL;

  IF array_length(v_targets, 1) IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
    SELECT t, v_ntype, v_title, v_body, 'accident', v_accident
      FROM unnest(v_targets) AS t;
  END IF;

  SELECT value INTO v_gate FROM public.system_config WHERE key = 'accident_emails_enabled';
  v_emails_on := lower(COALESCE(v_gate, 'false')) IN ('true','t','1','on','yes');
  IF NOT v_emails_on THEN
    RETURN;
  END IF;

  SELECT value INTO v_to_raw     FROM public.system_config WHERE key = 'accident_email_to';
  SELECT value INTO v_cc_raw     FROM public.system_config WHERE key = 'accident_email_cc';
  SELECT value INTO v_prefix     FROM public.system_config WHERE key = 'accident_email_subject_prefix';

  SELECT COALESCE(array_agg(DISTINCT e), '{}'::text[]) INTO v_emails
    FROM (
      SELECT lower(btrim(x)) AS e
        FROM regexp_split_to_table(
               COALESCE(v_to_raw, '') || E'\n' || COALESCE(v_cc_raw, ''),
               '[,;\n]') AS x
    ) s
   WHERE s.e ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$';

  IF array_length(v_emails, 1) IS NULL THEN
    INSERT INTO public.workflow_notifications
      (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
    VALUES
      (ev.id, v_org, NULL, ev.event_type,
       jsonb_build_object('recipients', '[]'::jsonb, 'reason', 'no_accident_email_recipients'),
       0, 'skipped')
    ON CONFLICT (event_id) DO NOTHING;
    RETURN;
  END IF;

  SELECT jsonb_agg(jsonb_build_object('email', e))
    INTO v_recipients
    FROM unnest(v_emails) AS e;

  IF ev.actor_id IS NOT NULL THEN
    SELECT COALESCE(NULLIF(btrim(p.full_name), ''), NULLIF(btrim(p.username), ''), 'A user'),
           NULLIF(btrim(p.role), '')
      INTO v_actor_name, v_actor_role
      FROM public.profiles p
     WHERE p.id = ev.actor_id;
    IF v_actor_name IS NOT NULL THEN
      v_signature := v_actor_name
                     || CASE WHEN v_actor_role IS NOT NULL
                             THEN ' (' || v_actor_role || ')' ELSE '' END;
    END IF;
  END IF;

  v_subject := btrim(COALESCE(v_prefix, '') || ' ' || v_title);
  v_html := '<p>' || v_body || '</p>'
            || '<p style="color:#666;font-size:12px">Action by: ' || v_signature
            || ' - ' || v_ctx || '. Official record inside Tyre Pulse.</p>';

  v_wf_payload := jsonb_build_object(
    'event_type',      'workflow.step_advanced',
    'instance_id',     NULL,
    'definition_name', 'Accident case',
    'entity_type',     'accident',
    'entity_label',    v_ctx,
    'step_name',       v_title,
    'body',            v_body,
    'email',           jsonb_build_object('subject', v_subject, 'html', v_html),
    'push',            jsonb_build_object('title', v_title, 'body', v_body),
    'recipients',      v_recipients);

  INSERT INTO public.workflow_notifications
    (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
  VALUES
    (ev.id, v_org, NULL, ev.event_type, v_wf_payload,
     jsonb_array_length(v_recipients),
     CASE WHEN jsonb_array_length(v_recipients) = 0 THEN 'skipped' ELSE 'pending' END)
  ON CONFLICT (event_id) DO NOTHING;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.consume_event_accident_notify(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  acc          public.accidents%ROWTYPE;
  v_key        text;
  v_depts      text[];
  v_to         text[];
  v_cc         text[];
  v_esc        text[];
  v_all        text[];
  v_dept       text;
  v_recipients jsonb := '[]'::jsonb;
  v_emails_on  boolean;
  v_title      text;
  v_body       text;
  v_ntype      text;
  v_subject    text;
  v_html       text;
  v_escalate   boolean;
  v_fixed_to   text[];
  v_fixed_cc   text[];
  v_prefix     text;
  v_mail_recipients jsonb;
BEGIN
  IF ev.event_type NOT LIKE 'accident.%' THEN RETURN; END IF;
  BEGIN
    SELECT * INTO acc FROM public.accidents WHERE id = ev.entity_id::uuid;
  EXCEPTION WHEN others THEN RETURN; END;
  IF acc.id IS NULL THEN RETURN; END IF;

  v_escalate := ev.event_type IN ('accident.vor_sla_breach','accident.overdue');

  IF ev.event_type = 'accident.reported' THEN
    v_key := CASE WHEN acc.severity IN ('severe','fatal') OR acc.injuries THEN 'critical' ELSE 'reported' END;
  ELSIF ev.event_type = 'accident.stage_changed' THEN
    v_key := CASE acc.workflow_stage
      WHEN 'workshop_assessment' THEN 'workshop_assessed'
      WHEN 'repair_approval'     THEN 'repair_approval'
      WHEN 'insurance_claim'     THEN 'claim_submitted'
      WHEN 'final_inspection'    THEN 'final_inspection_pending'
      WHEN 'vehicle_release'     THEN 'released'
      WHEN 'closed'              THEN 'closed'
      ELSE NULL END;
  ELSIF ev.event_type = 'accident.claim_changed' THEN
    v_key := CASE acc.claim_status
      WHEN 'filed' THEN 'claim_submitted' WHEN 'approved' THEN 'claim_approved'
      WHEN 'settled' THEN 'claim_approved' WHEN 'rejected' THEN 'claim_rejected' ELSE NULL END;
  ELSIF ev.event_type = 'accident.vor_sla_breach' THEN
    v_key := 'vor_sla_breach';
  ELSIF ev.event_type = 'accident.overdue' THEN
    v_key := 'overdue';
  ELSE
    v_key := NULL;
  END IF;

  WITH m AS (
    SELECT rr.departments, rr.to_roles, rr.cc_roles, rr.escalate_roles
    FROM public.accident_routing_rules rr
    WHERE rr.organisation_id = acc.organisation_id AND rr.active
      AND (rr.event_key IS NULL OR rr.event_key = ev.event_type)
      AND (COALESCE(array_length(rr.match_severities,1),0)=0 OR acc.severity = ANY(rr.match_severities))
      AND (COALESCE(array_length(rr.match_types,1),0)=0 OR acc.accident_type = ANY(rr.match_types))
      AND (COALESCE(array_length(rr.match_sites,1),0)=0 OR acc.site = ANY(rr.match_sites))
      AND (COALESCE(array_length(rr.match_countries,1),0)=0 OR acc.country = ANY(rr.match_countries))
      AND (rr.min_cost IS NULL OR COALESCE(acc.estimated_damage_cost,acc.final_amount,acc.repair_cost,0) >= rr.min_cost)
      AND (NOT rr.require_injury OR acc.injuries)
      AND (NOT rr.require_vor OR acc.vor)
      AND (NOT rr.require_third_party OR acc.third_party_involved)
  )
  SELECT
    COALESCE((SELECT array_agg(DISTINCT d) FROM m, unnest(m.departments) d),'{}'),
    COALESCE((SELECT array_agg(DISTINCT d) FROM m, unnest(m.to_roles) d),'{}'),
    COALESCE((SELECT array_agg(DISTINCT d) FROM m, unnest(m.cc_roles) d),'{}'),
    COALESCE((SELECT array_agg(DISTINCT d) FROM m, unnest(m.escalate_roles) d),'{}')
  INTO v_depts, v_to, v_cc, v_esc;

  IF COALESCE(array_length(v_to,1),0)=0 THEN v_to := ARRAY['Admin','Manager','Director']; END IF;
  IF v_escalate THEN
    v_all := (SELECT array_agg(DISTINCT x) FROM unnest(v_to || v_cc || COALESCE(v_esc,'{}')) x);
  ELSE
    v_all := (SELECT array_agg(DISTINCT x) FROM unnest(v_to || v_cc) x);
  END IF;
  v_dept := NULLIF(array_to_string(v_depts, ', '), '');
  IF v_dept IS NULL THEN v_dept := COALESCE(acc.department,'Operations'); END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id',p.id,'email',u.email,'push_token',t.tok,'role',p.role)),'[]'::jsonb)
    INTO v_recipients
  FROM public.profiles p
  LEFT JOIN auth.users u ON u.id = p.id
  LEFT JOIN LATERAL public._user_push_tokens(p.id) t(tok) ON true
  WHERE p.organisation_id = acc.organisation_id
    AND COALESCE(p.locked,false)=false AND (p.approved IS NULL OR p.approved = true)
    AND p.role = ANY(v_all)
    AND (p.site IS NULL OR btrim(p.site)='' OR upper(p.site)=upper(COALESCE(acc.site,''))
         OR upper(COALESCE(acc.site,'')) = ANY(SELECT upper(x) FROM unnest(COALESCE(p.sites,'{}'::text[])) x))
    AND (COALESCE(array_length(p.country,1),0)=0 OR acc.country IS NULL OR acc.country = ANY(p.country));

  v_ntype := CASE WHEN v_key IN ('critical','vor_sla_breach','overdue') THEN 'warning'
                  WHEN ev.event_type='accident.stage_changed' AND acc.workflow_stage='closed' THEN 'success'
                  ELSE 'accident' END;
  v_title := CASE ev.event_type
    WHEN 'accident.reported' THEN 'New accident '||COALESCE(acc.reference_no,'')||' ('||public.accident_severity_label(acc.severity)||')'
    WHEN 'accident.stage_changed' THEN 'Accident '||COALESCE(acc.reference_no,'')||' -> '||public.accident_stage_label(acc.workflow_stage)
    WHEN 'accident.claim_changed' THEN 'Claim '||COALESCE(acc.claim_status,'')||' - '||COALESCE(acc.reference_no,'')
    WHEN 'accident.vor_changed' THEN CASE WHEN acc.vor THEN 'Vehicle OFF ROAD - '||COALESCE(acc.reference_no,'') ELSE 'Vehicle back on road - '||COALESCE(acc.reference_no,'') END
    WHEN 'accident.vor_sla_breach' THEN 'VOR SLA BREACH - '||COALESCE(acc.reference_no,'')
    WHEN 'accident.overdue' THEN 'OVERDUE - '||COALESCE(acc.reference_no,'')
    ELSE 'Accident '||COALESCE(acc.reference_no,'') END;
  v_body := COALESCE(acc.asset_no,'')||' at '||COALESCE(acc.site,'')||' | '
            ||public.accident_stage_label(acc.workflow_stage)||' | Action: '||public.accident_pending_action(acc.workflow_stage);

  -- In-app notifications: always, to the role-resolved recipients (unchanged).
  IF jsonb_array_length(v_recipients) > 0 THEN
    INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
    SELECT DISTINCT (r->>'user_id')::uuid, v_ntype, v_title, v_body, 'accident', acc.id
    FROM jsonb_array_elements(v_recipients) r;
  END IF;

  v_emails_on := lower(btrim(COALESCE((SELECT value FROM public.system_config WHERE key='accident_emails_enabled'),'false'),'"'))
                 IN ('true','1','on','yes');
  IF v_emails_on AND v_key IS NOT NULL THEN
    SELECT public.accident_apply_tokens(t.subject, acc, v_dept),
           public.accident_apply_tokens(t.body_html, acc, v_dept)
      INTO v_subject, v_html
      FROM public.accident_email_templates t
      WHERE t.organisation_id = acc.organisation_id AND t.key = v_key AND t.active AND t.approved
      LIMIT 1;
    IF v_subject IS NOT NULL THEN
      -- Fixed-mailbox override (V428/V432): admin-configured real accident mailbox.
      v_fixed_to := ARRAY(
        SELECT btrim(x) FROM regexp_split_to_table(
          btrim(COALESCE((SELECT value FROM public.system_config WHERE key='accident_email_to'),''),'"'),
          '[,;\s]+') AS x
        WHERE btrim(x) <> '' AND position('@' in x) > 1);
      v_fixed_cc := ARRAY(
        SELECT btrim(x) FROM regexp_split_to_table(
          btrim(COALESCE((SELECT value FROM public.system_config WHERE key='accident_email_cc'),''),'"'),
          '[,;\s]+') AS x
        WHERE btrim(x) <> '' AND position('@' in x) > 1);
      v_prefix := btrim(btrim(COALESCE((SELECT value FROM public.system_config WHERE key='accident_email_subject_prefix'),''),'"'));

      IF COALESCE(array_length(v_fixed_to,1),0) > 0 THEN
        -- keep only role recipients that carry a push_token (email nulled so no
        -- staff email), then append the fixed To + CC as email-only recipients.
        v_mail_recipients := COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                     'user_id', x->>'user_id', 'email', NULL,
                     'push_token', x->>'push_token', 'role', x->>'role'))
              FROM jsonb_array_elements(v_recipients) x
             WHERE NULLIF(x->>'push_token','') IS NOT NULL), '[]'::jsonb)
          || COALESCE((SELECT jsonb_agg(jsonb_build_object('email', a)) FROM unnest(v_fixed_to) a), '[]'::jsonb)
          || COALESCE((SELECT jsonb_agg(jsonb_build_object('email', a)) FROM unnest(v_fixed_cc) a), '[]'::jsonb);
        IF v_prefix <> '' AND position(v_prefix in v_subject) <> 1 THEN
          v_subject := v_prefix || ' ' || v_subject;
        END IF;
      ELSE
        v_mail_recipients := v_recipients;   -- legacy role-based per-user emails
      END IF;

      IF jsonb_array_length(v_mail_recipients) > 0 THEN
        INSERT INTO public.workflow_notifications
          (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
        VALUES
          (ev.id, acc.organisation_id, NULL, ev.event_type,
           jsonb_build_object('event_type',ev.event_type,'channel','accident','entity_id',acc.id::text,
             'email', jsonb_build_object('subject',v_subject,'html',v_html),
             'push',  jsonb_build_object('title',v_title,'body',v_body),
             'recipients', v_mail_recipients),
           (SELECT count(*) FROM jsonb_array_elements(v_mail_recipients) e WHERE NULLIF(e->>'email','') IS NOT NULL),
           'pending')
        ON CONFLICT (event_id) DO NOTHING;
      END IF;
    END IF;
  END IF;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.consume_event_approval_push(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_country    text  := NULLIF(ev.payload ->> 'country', '');
  v_label      text;
  v_def        text;
  v_recipients jsonb;
  v_payload    jsonb;
  v_entity     uuid;
BEGIN
  IF ev.event_type = 'inspection.approval_requested' THEN
    v_def   := 'Inspection';
    v_label := COALESCE(NULLIF(ev.payload ->> 'asset_no', ''), NULLIF(ev.payload ->> 'title', ''), 'An inspection');
  ELSE
    v_def   := 'Checklist';
    v_label := COALESCE(NULLIF(ev.payload ->> 'template_name', ''), 'A checklist');
  END IF;

  v_entity := CASE WHEN ev.entity_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                   THEN ev.entity_id::uuid END;

  -- In-app notification for EVERY eligible approver (token or not) so the web
  -- Approval Dashboard users see it in their bell too. Best-effort.
  BEGIN
    INSERT INTO public.notifications (user_id, type, title, body, entity_type, entity_id)
    SELECT p.id, 'approval',
           v_def || ' awaiting approval',
           v_label
             || CASE WHEN NULLIF(ev.payload ->> 'site', '') IS NOT NULL
                     THEN ' at ' || (ev.payload ->> 'site') ELSE '' END
             || ' needs your sign-off.',
           ev.entity_type, v_entity
      FROM public.profiles p
     WHERE p.role IN ('Admin', 'Manager', 'Director', 'Maintenance Supervisor')
       AND COALESCE(p.approved, false)
       AND NOT COALESCE(p.locked, false)
       AND (ev.organisation_id IS NULL
            OR p.organisation_id = ev.organisation_id
            OR p.org_id = ev.organisation_id)
       AND (v_country IS NULL
            OR p.country IS NULL OR cardinality(p.country) = 0
            OR v_country = ANY (p.country));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  -- Push channel (unchanged): only approvers with a registered device token.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', p.id, 'push_token', t.tok, 'role', p.role)), '[]'::jsonb)
    INTO v_recipients
    FROM public.profiles p
    CROSS JOIN LATERAL public._user_push_tokens(p.id) t(tok)
   WHERE p.role IN ('Admin', 'Manager', 'Director', 'Maintenance Supervisor')
     AND COALESCE(p.approved, false)
     AND NOT COALESCE(p.locked, false)
     AND (ev.organisation_id IS NULL
          OR p.organisation_id = ev.organisation_id
          OR p.org_id = ev.organisation_id)
     AND (v_country IS NULL
          OR p.country IS NULL OR cardinality(p.country) = 0
          OR v_country = ANY (p.country));

  v_payload := jsonb_build_object(
    'event_type',      'workflow.step_advanced',
    'instance_id',     NULL,
    'definition_name', v_def || ' approval',
    'entity_type',     ev.entity_type,
    'entity_label',    v_label || CASE WHEN NULLIF(ev.payload ->> 'site', '') IS NOT NULL
                                       THEN ' (' || (ev.payload ->> 'site') || ')' ELSE '' END,
    'step_name',       'Supervisor approval',
    'recipients',      v_recipients);

  INSERT INTO public.workflow_notifications
    (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
  VALUES
    (ev.id, ev.organisation_id, NULL, ev.event_type, v_payload,
     jsonb_array_length(v_recipients),
     CASE WHEN jsonb_array_length(v_recipients) = 0 THEN 'skipped' ELSE 'pending' END)
  ON CONFLICT (event_id) DO NOTHING;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.consume_event_assignment_push(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user       uuid := NULLIF(ev.payload ->> 'user_id', '')::uuid;
  v_job        uuid := NULLIF(ev.payload ->> 'job_id', '')::uuid;
  v_country    text := NULLIF(ev.payload ->> 'country', '');
  v_wo_no      text;
  v_asset      text;
  v_label      text;
  v_recipients jsonb;
  v_payload    jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN;  -- no assignee to notify
  END IF;

  -- Work-order label (skip cleanly if the job is missing).
  SELECT wo.work_order_no, wo.asset_no
    INTO v_wo_no, v_asset
    FROM public.work_orders wo
   WHERE wo.id = v_job
   LIMIT 1;

  v_label := COALESCE(
    CASE WHEN NULLIF(v_wo_no, '') IS NOT NULL
         THEN 'work order ' || v_wo_no
              || CASE WHEN NULLIF(v_asset, '') IS NOT NULL THEN ' (asset ' || v_asset || ')' ELSE '' END
    END,
    CASE WHEN NULLIF(v_asset, '') IS NOT NULL THEN 'a job on asset ' || v_asset END,
    'a job');

  -- Recipient = the assignee only: approved, org-matched, country-visible, push-enabled.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'user_id', p.id, 'push_token', t.tok, 'role', p.role)), '[]'::jsonb)
    INTO v_recipients
    FROM public.profiles p
    CROSS JOIN LATERAL public._user_push_tokens(p.id) t(tok)
   WHERE p.id = v_user
     AND COALESCE(p.approved, false)
     AND (ev.organisation_id IS NULL
          OR p.organisation_id = ev.organisation_id
          OR p.org_id = ev.organisation_id)
     AND (v_country IS NULL
          OR p.country IS NULL OR cardinality(p.country) = 0
          OR v_country = ANY (p.country));

  v_payload := jsonb_build_object(
    'event_type',      'workflow.assigned',   -- drives the workflow-notify edge fn message
    'instance_id',     NULL,
    'definition_name', 'Job',
    'entity_type',     'work_order',
    'entity_label',    v_label,
    'step_name',       'assignment',
    'recipients',      v_recipients);

  INSERT INTO public.workflow_notifications
    (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
  VALUES
    (ev.id, ev.organisation_id, NULL, ev.event_type, v_payload,
     jsonb_array_length(v_recipients),
     CASE WHEN jsonb_array_length(v_recipients) = 0 THEN 'skipped' ELSE 'pending' END)
  ON CONFLICT (event_id) DO NOTHING;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.consume_event_rules(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r      public.business_rules%ROWTYPE;
  a      jsonb;
  v_pass boolean;
  v_emit text;
BEGIN
  FOR r IN
    SELECT * FROM public.business_rules
     WHERE active AND trigger_type = 'event'
       AND ev.event_type = ANY (event_types)
       AND (organisation_id IS NULL OR ev.organisation_id IS NULL OR organisation_id = ev.organisation_id)
  LOOP
    IF EXISTS (SELECT 1 FROM public.rule_executions WHERE rule_id = r.id AND event_id = ev.id) THEN
      CONTINUE;
    END IF;
    IF r.cooldown_minutes > 0 AND r.last_triggered_at IS NOT NULL
       AND r.last_triggered_at + make_interval(mins => r.cooldown_minutes) > now() THEN
      INSERT INTO public.rule_executions (rule_id, organisation_id, event_id, status)
      VALUES (r.id, ev.organisation_id, ev.id, 'skipped_cooldown');
      CONTINUE;
    END IF;
    SELECT COALESCE(bool_and(public.rule_condition_passes(ev.payload, c)), true)
      INTO v_pass FROM jsonb_array_elements(r.conditions) c;
    IF NOT v_pass THEN
      INSERT INTO public.rule_executions (rule_id, organisation_id, event_id, status)
      VALUES (r.id, ev.organisation_id, ev.id, 'conditions_not_met');
      CONTINUE;
    END IF;
    FOR a IN SELECT * FROM jsonb_array_elements(r.actions) LOOP
      IF a ->> 'type' = 'notify_role' THEN
        PERFORM public.notify_role_in_org(
          a ->> 'role', ev.organisation_id, 'rule',
          COALESCE(a ->> 'title', 'Rule triggered: ' || r.name),
          COALESCE(a ->> 'message',
                   r.name || ' matched ' || ev.event_type ||
                   COALESCE(' for ' || (ev.payload ->> 'asset_no'), '') || '.'),
          'business_rule', r.id);
      ELSIF a ->> 'type' = 'emit_event' THEN
        v_emit := a ->> 'event_type';
        IF v_emit NOT LIKE 'rule.%' THEN
          v_emit := 'rule.' || v_emit;
        END IF;
        PERFORM public.emit_domain_event(
          v_emit, 'business_rule', r.id::text,
          ev.payload || jsonb_build_object('rule_name', r.name, 'source_event', ev.event_type),
          ev.organisation_id, NULL);
      END IF;
    END LOOP;
    UPDATE public.business_rules
       SET triggered_count = triggered_count + 1, last_triggered_at = now()
     WHERE id = r.id;
    INSERT INTO public.rule_executions (rule_id, organisation_id, event_id, status, detail)
    VALUES (r.id, ev.organisation_id, ev.id, 'actioned',
            jsonb_build_object('event_type', ev.event_type, 'actions', r.actions));
  END LOOP;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.consume_event_webhooks(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.webhook_deliveries
    (subscription_id, event_id, organisation_id, event_type, payload)
  SELECT s.id, ev.id, s.organisation_id, ev.event_type,
         jsonb_build_object('id', ev.id, 'type', ev.event_type, 'entity_type', ev.entity_type,
           'entity_id', ev.entity_id, 'created_at', ev.created_at, 'data', ev.payload)
    FROM public.webhook_subscriptions s
   WHERE s.active
     AND s.organisation_id IS NOT DISTINCT FROM ev.organisation_id
     AND (s.event_types IS NULL OR ev.event_type = ANY (s.event_types))
  ON CONFLICT (subscription_id, event_id) DO NOTHING;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.consume_event_workflow_notify(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inst        public.workflow_instances%ROWTYPE;
  v_step        jsonb;
  v_step_name   text;
  v_role        text;
  v_user_id     text;
  v_recipients  jsonb := '[]'::jsonb;
  v_payload     jsonb;
BEGIN
  IF ev.event_type NOT IN ('workflow.step_advanced','workflow.approved',
                           'workflow.rejected','workflow.returned') THEN
    RETURN;
  END IF;
  BEGIN
    SELECT * INTO v_inst FROM public.workflow_instances
     WHERE id = ev.entity_id::uuid;
  EXCEPTION WHEN others THEN
    RETURN;
  END;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  v_step_name := COALESCE(ev.payload ->> 'step', '');
  IF ev.event_type = 'workflow.step_advanced' THEN
    v_step := v_inst.steps -> v_inst.current_step;
    v_step_name := COALESCE(v_step ->> 'name', v_step_name);
    IF lower(COALESCE(v_step ->> 'assignee_type','role')) = 'user'
       AND COALESCE(v_step ->> 'approver_user_id','') <> '' THEN
      v_user_id := v_step ->> 'approver_user_id';
      SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) INTO v_recipients
        FROM (
          SELECT jsonb_build_object('user_id', p.id, 'email', u.email,
                   'push_token', t.tok, 'phone', NULL, 'role', p.role) AS r
            FROM public.profiles p
            LEFT JOIN auth.users u ON u.id = p.id
            LEFT JOIN LATERAL public._user_push_tokens(p.id) t(tok) ON true
           WHERE p.id = v_user_id::uuid
             AND COALESCE(p.locked, false) = false
             AND (p.approved IS NULL OR p.approved = true)
        ) s;
    ELSE
      v_role := lower(regexp_replace(COALESCE(v_step ->> 'approver_role',''), '\s+', '_', 'g'));
      SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) INTO v_recipients
        FROM (
          SELECT jsonb_build_object('user_id', p.id, 'email', u.email,
                   'push_token', t.tok, 'phone', NULL, 'role', p.role) AS r
            FROM public.profiles p
            LEFT JOIN auth.users u ON u.id = p.id
            LEFT JOIN LATERAL public._user_push_tokens(p.id) t(tok) ON true
           WHERE lower(regexp_replace(COALESCE(p.role,''), '\s+', '_', 'g')) = v_role
             AND COALESCE(p.locked, false) = false
             AND (p.approved IS NULL OR p.approved = true)
             AND (v_inst.organisation_id IS NULL
                  OR p.organisation_id = v_inst.organisation_id)
        ) s;
    END IF;
  ELSE
    IF v_inst.started_by IS NOT NULL THEN
      SELECT COALESCE(jsonb_agg(r), '[]'::jsonb) INTO v_recipients
        FROM (
          SELECT jsonb_build_object('user_id', p.id, 'email', u.email,
                   'push_token', t.tok, 'phone', NULL, 'role', p.role) AS r
            FROM public.profiles p
            LEFT JOIN auth.users u ON u.id = p.id
            LEFT JOIN LATERAL public._user_push_tokens(p.id) t(tok) ON true
           WHERE p.id = v_inst.started_by
             AND COALESCE(p.locked, false) = false
        ) s;
    END IF;
  END IF;
  v_payload := jsonb_build_object(
    'event_type', ev.event_type, 'instance_id', v_inst.id,
    'definition_name', v_inst.definition_name, 'entity_type', v_inst.entity_type,
    'entity_label', COALESCE(v_inst.entity_label, v_inst.entity_type),
    'step_name', v_step_name, 'comment', ev.payload ->> 'comment',
    'recipients', v_recipients);
  INSERT INTO public.workflow_notifications
    (event_id, organisation_id, instance_id, event_type, payload, recipient_count, status)
  VALUES
    (ev.id, v_inst.organisation_id, v_inst.id, ev.event_type, v_payload,
     jsonb_array_length(v_recipients),
     CASE WHEN jsonb_array_length(v_recipients) = 0 THEN 'skipped' ELSE 'pending' END)
  ON CONFLICT (event_id) DO NOTHING;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.consume_event_workflows(ev public.domain_events)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  d record;
BEGIN
  FOR d IN
    SELECT id FROM public.workflow_definitions
     WHERE active
       AND trigger_event = ev.event_type
       AND (organisation_id IS NULL OR ev.organisation_id IS NULL
            OR organisation_id = ev.organisation_id)
  LOOP
    PERFORM public._workflow_launch(
      d.id, COALESCE(ev.entity_type, 'event'), ev.entity_id,
      COALESCE(ev.payload ->> 'asset_no', ev.entity_type || ' ' || COALESCE(ev.entity_id, '')),
      ev.payload, ev.actor_id, ev.id);
  END LOOP;
END;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.current_support_session()
 RETURNS public.support_sessions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select s.* from public.support_sessions s
  where s.super_admin_id = auth.uid() and public.is_super_admin()
    and s.active = true and s.ended_at is null and (s.expires_at is null or s.expires_at > now())
  order by s.started_at desc limit 1;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.end_support_session(p_id uuid)
 RETURNS public.support_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.support_sessions;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then raise exception 'Permission denied: super admin required'; end if;
  update public.support_sessions set active=false, ended_at=coalesce(ended_at, now())
   where id = p_id and super_admin_id = auth.uid() returning * into v_row;
  if v_row.id is null then raise exception 'Support session not found'; end if;
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'support_session_end', v_row.id, 'support_session',
    jsonb_build_object('target_org_id', v_row.target_org_id, 'ended_at', v_row.ended_at));
  return v_row;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.ensure_org_subscription()
 RETURNS public.org_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid := public.app_current_org();
  v_row public.org_subscriptions%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.org_subscriptions
   WHERE organisation_id IS NOT DISTINCT FROM v_org ORDER BY created_at LIMIT 1;
  IF NOT FOUND THEN
    INSERT INTO public.org_subscriptions
      (organisation_id, plan_code, status, billing_interval, seats,
       trial_ends_at, current_period_start, current_period_end)
    VALUES (v_org, 'trial', 'trialing', 'monthly', 1,
       now() + interval '14 days', now(), now() + interval '14 days')
    ON CONFLICT (organisation_id) DO NOTHING;
    SELECT * INTO v_row FROM public.org_subscriptions
     WHERE organisation_id IS NOT DISTINCT FROM v_org ORDER BY created_at LIMIT 1;
  END IF;
  RETURN v_row;
END $function$;
-- @@
CREATE OR REPLACE FUNCTION public.has_approver_signature(r public.inspections)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$ select r.approver_signed $function$;
