-- @@
CREATE OR REPLACE FUNCTION public.my_pending_approvals()
 RETURNS SETOF public.workflow_instances
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT w.* FROM workflow_instances w WHERE w.status IN ('pending','in_review','returned')
 AND (w.organisation_id IS NULL OR w.organisation_id=app_current_org())
 AND approval_workflow_visible(w.organisation_id,w.entity_type,w.context)
 AND CASE WHEN coalesce(w.context->>'approval_matrix','false')='true' THEN
  approval_private.represented_actor(w) IS NOT NULL
  AND (NOT coalesce((w.steps->w.current_step->>'distinct_reviewer')::boolean,true) OR NOT EXISTS(SELECT 1 FROM workflow_step_events e WHERE e.instance_id=w.id AND e.action='approved'
   AND (e.actor_id IN(auth.uid(),approval_private.represented_actor(w)) OR e.device_info->>'represented_actor_id' IN(auth.uid()::text,approval_private.represented_actor(w)::text))))
 ELSE lower(get_my_role())='admin' OR w.steps->w.current_step->>'approver_user_id'=auth.uid()::text
  OR lower(regexp_replace(coalesce(w.steps->w.current_step->>'approver_role',''),'\s+','_','g'))=lower(regexp_replace(coalesce(get_my_role(),''),'\s+','_','g')) END
 ORDER BY w.started_at
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.seal_audit_day(p_source text, p_day date)
 RETURNS public.audit_seals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_today date := (now() at time zone 'UTC')::date;
  v_prev  text;
  v_cnt   bigint;
  v_dig   text;
  v_row   public.audit_seals;
begin
  if p_day is null or p_day >= v_today then
    raise exception 'Only a closed day (before today, UTC) can be sealed' using errcode = '22023';
  end if;
  select * into v_row from public.audit_seals where source = p_source and day = p_day;
  if found then return v_row; end if;
  if exists (select 1 from public.audit_seals where source = p_source and day > p_day) then
    raise exception 'A later day is already sealed; seals must be created in day order' using errcode = '22023';
  end if;
  select chain_digest into v_prev from public.audit_seals
   where source = p_source and day < p_day order by day desc limit 1;
  select d.row_count, d.digest into v_cnt, v_dig from public._audit_day_digest(p_source, p_day) d;
  insert into public.audit_seals (source, day, row_count, digest, prev_digest, chain_digest)
  values (p_source, p_day, v_cnt, v_dig, v_prev,
          encode(extensions.digest(coalesce(v_prev, 'GENESIS') || v_dig, 'sha256'), 'hex'))
  returning * into v_row;
  return v_row;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.start_support_session(p_target_org uuid, p_reason text, p_minutes integer DEFAULT 30, p_mode text DEFAULT 'read_only'::text)
 RETURNS public.support_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.support_sessions; v_minutes integer; v_mode text;
begin
  if not public._console_ip_allowed() then
    raise exception 'Console access is not allowed from this network' using errcode = '42501';
  end if;

  if not public.is_super_admin() then raise exception 'Permission denied: super admin required'; end if;
  if p_target_org is null then raise exception 'A target organisation is required'; end if;
  if not exists (select 1 from public.organisations where id = p_target_org) then raise exception 'Unknown target organisation'; end if;
  if p_reason is null or btrim(p_reason) = '' then raise exception 'A reason is required to open a support session'; end if;
  v_mode := lower(coalesce(nullif(btrim(p_mode), ''), 'read_only'));
  if v_mode not in ('read_only','edit') then raise exception 'Invalid mode: %', p_mode; end if;
  v_minutes := coalesce(p_minutes, 30);
  if v_minutes < 1 then v_minutes := 1; end if;
  if v_minutes > 480 then v_minutes := 480; end if;
  update public.support_sessions set active=false, ended_at=now()
   where super_admin_id = auth.uid() and active=true and ended_at is null;
  insert into public.support_sessions (super_admin_id, target_org_id, reason, mode, started_at, expires_at, active)
  values (auth.uid(), p_target_org, btrim(p_reason), v_mode, now(), now() + make_interval(mins => v_minutes), true)
  returning * into v_row;
  -- audit into the existing console_sessions sink directly (correct uuid typing)
  insert into public.console_sessions (admin_id, action, target_id, target_type, details)
  values (auth.uid(), 'support_session_start', v_row.id, 'support_session',
    jsonb_build_object('target_org_id', v_row.target_org_id, 'mode', v_row.mode, 'reason', v_row.reason, 'expires_at', v_row.expires_at, 'minutes', v_minutes));
  return v_row;
end;
$function$;
-- @@
CREATE OR REPLACE FUNCTION public.tp_employee_action_transition(p_action_id uuid, p_status text, p_reason text DEFAULT NULL::text, p_resolution text DEFAULT NULL::text)
 RETURNS public.action_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_old public.action_items; v_updated public.action_items; v_next text:=lower(btrim(coalesce(p_status,'')));
begin
 if auth.uid() is null then raise exception 'Sign-in required' using errcode='42501'; end if;
 if v_next not in ('acknowledged','in_progress','blocked','resolved') then raise exception 'Invalid transition' using errcode='22023'; end if;
 select * into v_old from public.action_items a
 where a.id=p_action_id and a.assigned_user_id=auth.uid()
   and a.organisation_id=public.app_current_org() for update;
 if not found then raise exception 'Action not assigned or inaccessible' using errcode='42501'; end if;
 if not exists(select 1 from public.profiles p where p.id=auth.uid()
   and (p.organisation_id=v_old.organisation_id or p.org_id=v_old.organisation_id)
   and coalesce(p.approved,true) and not coalesce(p.locked,false)) then
   raise exception 'Inactive employee account' using errcode='42501';
 end if;
 if not (
  (v_old.status='open' and v_next in ('acknowledged','in_progress','blocked')) or
  (v_old.status='acknowledged' and v_next in ('in_progress','blocked')) or
  (v_old.status='in_progress' and v_next in ('blocked','resolved')) or
  (v_old.status='blocked' and v_next='in_progress')
 ) then raise exception 'Disallowed state transition' using errcode='22023'; end if;
 if v_next='blocked' and length(btrim(coalesce(p_reason,'')))<5 then
  raise exception 'Block reason required' using errcode='22023'; end if;
 if v_next='resolved' and length(btrim(coalesce(p_resolution,'')))<10 then
  raise exception 'Completion details required' using errcode='22023'; end if;
 update public.action_items set status=v_next,
   blocked_reason=case when v_next='blocked' then left(btrim(p_reason),4000) else blocked_reason end,
   resolution=case when v_next='resolved' then left(btrim(p_resolution),4000) else resolution end,
   completed_at=case when v_next='resolved' then now() else completed_at end,
   updated_at=now()
 where id=p_action_id returning * into v_updated;
 return v_updated;
end $function$;
-- @@
CREATE OR REPLACE FUNCTION public.transition_action_item(p_action_item_id uuid, p_to_status text, p_reason text DEFAULT NULL::text, p_resolution text DEFAULT NULL::text, p_approval_note text DEFAULT NULL::text)
 RETURNS public.action_items
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_item public.action_items;
begin
  update public.action_items
  set status = lower(btrim(p_to_status)),
      blocked_reason = case when lower(btrim(p_to_status)) = 'blocked' then nullif(btrim(p_reason),'') else blocked_reason end,
      escalated_reason = case when lower(btrim(p_to_status)) = 'escalated' then nullif(btrim(p_reason),'') else escalated_reason end,
      resolution = case when lower(btrim(p_to_status)) in ('resolved','dismissed') then nullif(btrim(p_resolution),'') else resolution end,
      approval_note = coalesce(nullif(btrim(p_approval_note),''), approval_note)
  where id = p_action_item_id
    and organisation_id = public.app_current_org()
  returning * into v_item;
  if not found then raise exception 'Action item not found or inaccessible' using errcode = 'P0002'; end if;
  return v_item;
end $function$;
